// Generated security helpers for promoRedemptions
import { eq, and, isNull, sql, type SQL } from 'drizzle-orm';
import type { Context } from 'hono';
import { promoRedemptions } from './schema';
import type { AppContext } from '../../lib/types';
export { promoRedemptions };

/**
 * Firewall conditions for promoRedemptions
 * Pattern: Owner only
 */
export function buildFirewallConditions(ctx: AppContext, _db?: unknown, opts?: { skipTenantScopes?: boolean }): SQL | undefined {
  if (opts?.skipTenantScopes) {
    return isNull(promoRedemptions.deletedAt);
  }
  // Sysadmin escape: cross-tenant DB-admin tier bypasses tenant scopes
  // but still respects soft-delete when present. Emitted because
  // `cms.sysadmin: true` is set on the project; tenant predicates
  // (org/owner/team/relationship-via) are stripped from this branch.
  if (ctx.userRole === 'sysadmin') {
    return undefined;
  }
  // Null-claim guard (conformance F4): a caller whose bound ctx claim is
  // absent gets a clean deny instead of binding `undefined` into the query
  // (driver-level error). Healthy-path predicates below are unchanged.
  if (ctx.userId == null) {
    return sql`1 = 0`;
  }
  return and(eq(promoRedemptions.ownerId, ctx.userId!), isNull(promoRedemptions.deletedAt));
}

/**
 * Helper for manual routes — wraps handler with auth check and firewall.
 * Pulls the request-scoped Drizzle db client off the Hono context and
 * threads it into buildFirewallConditions so relationship-role subqueries
 * (`via:` predicates) resolve at runtime.
 */
export async function withFirewall<T>(
  c: Context,
  handler: (ctx: AppContext, firewall: SQL | undefined) => Promise<T>
): Promise<Response | T> {
  const ctx = c.get('ctx') as AppContext;
  if (!ctx?.userId) {
    return c.json({
      error: 'Authentication required',
      layer: 'authentication',
      code: 'AUTH_MISSING',
      hint: 'Include Authorization header with Bearer token',
    }, 401);
  }
  const db = c.get('db' as never) as any;
  const firewall = buildFirewallConditions(ctx, db);
  return handler(ctx, firewall);
}

